mapper.select:
SELECT log_id, res_name, opt_name, res_id, res_title, user_name, dept_name, access_time, oper_ip, oper_location, status, user_id, dept_id, create_by, create_time, update_by, update_time, remark FROM sys_res_log WHERE status = '0'
AND res_name = #{query.moduleFilter}
ORDER BY access_time DESC
